/* ===== 纯函数区（第一个无属性 script）：可被 Node _test.js 提取并断言 ===== */
function parseTiff(tiff){
  var dv = new DataView(tiff.buffer, tiff.byteOffset, tiff.byteLength);
  var le = (dv.getUint8(0)===0x49 && dv.getUint8(1)===0x49); // II = little endian
  function u16(o){ return dv.getUint16(o, le); }
  function u32(o){ return dv.getUint32(o, le); }
  if(dv.getUint16(2, le)!==0x2A) return null;
  var result = {};
  function readIfd(off){
    if(off+2 > dv.byteLength) return;
    var n = u16(off);
    for(var i=0;i<n;i++){
      var e = off + 2 + i*12;
      var tag = u16(e), type = u16(e+2), count = u32(e+4);
      var valOff = e+8;
      var value;
      if(type===2){ // ASCII
        var bytes = count, strOff = (bytes<=4) ? valOff : u32(valOff), s='';
        for(var k=0;k<bytes;k++){ var c=dv.getUint8(strOff+k); if(c===0) break; s+=String.fromCharCode(c); }
        value = s;
      } else if(type===3){ value = u16(valOff); }
      else if(type===4){ value = u32(valOff); }
      else if(type===1){ value = dv.getUint8(valOff); }
      else { value = null; }
      result[tag] = value;
    }
  }
  readIfd(u32(4));
  if(result[0x8769]!=null) readIfd(result[0x8769]); // Exif sub-IFD
  var NAMES = {0x010F:'Make',0x0110:'Model',0x0132:'DateTime',0x0112:'Orientation',
    0x829A:'ExposureTime',0x8827:'ISO',0x9003:'DateTimeOriginal',0xA002:'PixelXDimension',0xA003:'PixelYDimension'};
  var named = {};
  Object.keys(result).forEach(function(t){ var n=NAMES[t]; if(n) named[n]=result[t]; });
  return named;
}
function parseExifFromJpeg(bytes){
  if(bytes[0]!==0xFF || bytes[1]!==0xD8) return null;
  var i=2;
  while(i+3 < bytes.length){
    if(bytes[i]!==0xFF) break;
    var marker=bytes[i+1];
    if(marker===0xD9) break;
    if(marker>=0xD0 && marker<=0xD9){ i+=2; continue; }
    var len=(bytes[i+2]<<8)|bytes[i+3];
    if(marker===0xE1 && bytes[i+4]===0x45 && bytes[i+5]===0x78 && bytes[i+6]===0x69 &&
        bytes[i+7]===0x66 && bytes[i+8]===0x00 && bytes[i+9]===0x00){
      var tiff = bytes.subarray(i+10, i+2+len);
      return parseTiff(tiff);
    }
    i += len+2;
  }
  return null;
}
function stripExif(bytes){
  if(bytes[0]!==0xFF || bytes[1]!==0xD8) return bytes;
  var out=[0xFF,0xD8], i=2;
  while(i+1 < bytes.length){
    if(bytes[i]!==0xFF){ break; }
    var marker=bytes[i+1];
    if(marker===0xD9){ out.push(0xFF,0xD9); break; }
    if(marker>=0xD0 && marker<=0xD9){ out.push(0xFF,marker); i+=2; continue; }
    var len=(bytes[i+2]<<8)|bytes[i+3];
    var isExif = (marker===0xE1) && bytes[i+4]===0x45 && bytes[i+5]===0x78 && bytes[i+6]===0x69 &&
                 bytes[i+7]===0x66 && bytes[i+8]===0x00 && bytes[i+9]===0x00;
    if(!isExif){ for(var k=0;k<len+2;k++) out.push(bytes[i+k]); }
    i += len+2;
  }
  return Uint8Array.from(out);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseTiff:parseTiff, parseExifFromJpeg:parseExifFromJpeg, stripExif:stripExif };
}
if (typeof window !== 'undefined') {
  window.ExifForgePure = { parseTiff:parseTiff, parseExifFromJpeg:parseExifFromJpeg, stripExif:stripExif };
}
